p = Path("index.html")
t = p.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n")

# F08 inside layerViews
if re.search(r"F08:\(\)=>", t):
    t2, n = re.subn(r"F08:\(\)=>[\s\S]*?(?=(?:\n(?:L\d|W\d|PCV\d|function |const |[A-Z][A-Z0-9_]+:\(\)=>)|\n\}\s*;))", F08_BLOCK, t, count=1)
    if n != 1:
        t2, n = re.subn(r"F08:\(\)=>[\s\S]*?(?=,\s*\n(?:[A-Z0-9_]+):|\n\}\s*;)", F08_BLOCK, t, count=1)
    if n == 1:
        t = t2
        print("F08 replaced")
    else:
        raise SystemExit("F08 replace failed")
else:
    raise SystemExit("F08 key not found")

for key, block in [("PCV1", PCV1_BLOCK), ("PCV2", PCV2_BLOCK), ("PCV3", PCV3_BLOCK), ("PCV4", PCV4_BLOCK)]:
    pattern = rf"{key}:\(\)=>[\s\S]*?(?=(?:\nPCV\d:)|(?:\n\}}))"
    t2, n = re.subn(pattern, block, t, count=1)
    if n != 1:
        raise SystemExit(f"{key} replace failed matches={n}")
    t = t2
    print(f"{key} installed")

# Safety checks
for needle in ["INTELLIGENCE CHAIN (11 STEPS)", "View A — Control Board", "NIV = AC", "INTERVENE", "SPECIALIST SIGN-OFF"]:
    if needle not in t:
        raise SystemExit(f"Safety missing: {needle}")

p.write_text(t, encoding="utf-8", newline="\n")
print("DONE: F08 + PCV1-4 matched to PNG designs")
